import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source implementing exact GELU for FP16 tensors
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>

// -----------------------------------------------------------------------------
// GELU kernel for __half (FP16) data
// -----------------------------------------------------------------------------
__global__ void gelu_kernel(const __half* __restrict__ input,
                            __half* __restrict__ output,
                            size_t N) {
    const size_t idx   = blockIdx.x * blockDim.x + threadIdx.x;
    const size_t stride = gridDim.x * blockDim.x;
    constexpr float sqrt_2 = 1.4142135623730951f;  // sqrt(2)

    for (size_t i = idx; i < N; i += stride) {
        // Load FP16, convert to FP32 for high‑precision math
        float x = __half2float(input[i]);

        // Exact GELU: 0.5 * x * (1 + erf(x / sqrt(2)))
        float y = 0.5f * x * (1.0f + erff(x / sqrt_2));

        // Store result back as FP16
        output[i] = __float2half(y);
    }
}

// -----------------------------------------------------------------------------
// C++ entry point called from Python
// -----------------------------------------------------------------------------
torch::Tensor gelu_forward(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "gelu_forward: input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kFloat16,
                "gelu_forward: input must have dtype torch.float16");

    auto output = torch::empty_like(input);
    const size_t N = static_cast<size_t>(input.numel());

    const int threads = 256;
    const int blocks = static_cast<int>((N + threads - 1) / threads);

    gelu_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        N
    );

    // Propagate launch errors, if any
    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "gelu_forward kernel launch failed");

    return output;
}
'''  # end of cuda_source

# Compile the inline extension
gelu_mod = load_inline(name='gelu_cuda',
                       cpp_sources='',
                       cuda_sources=cuda_source,
                       functions=['gelu_forward'],
                       verbose=False)

# -------------------------------------------------------------------------
# Model that uses the custom CUDA GELU implementation
# -------------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Expect FP16 CUDA tensor; the extension will enforce this
        return gelu_mod.gelu_forward(x)


# -------------------------------------------------------------------------
# Helper functions matching the reference API
# -------------------------------------------------------------------------
def get_inputs():
    # Use FP16 tensors on CUDA to match the kernel expectations
    x = torch.rand(4096, 393216, device='cuda', dtype=torch.float16)
    return [x]

def get_init_inputs():
    return []  # No special initialization needed
